\bibliography{refs}
\end{document}
EOF
cat > /tmp/repro-bib/refs.bib <<'EOF'
@article{testref,
  author = {Doe, John},
  title = {A Test Article},
  journal = {Journal of Testing},
  year = {2020},
  volume = {1},
  pages = {1--10}
}
EOF
